 await login(page,'admin');await page.getByRole('button',{name:'Kanban',exact:true}).click();await page.getByRole('button',{name:'Chọn bảng Kanban',exact:true}).click();await page.getByRole('option',{name:'Synthetic Kanban all '+browserName,exact:true}).click();await expect(page.locator('[data-kanban-task="ui-private-'+browserName+'"]')).toBeVisible();await page.getByRole('button',{name:'Đăng xuất',exact:true}).click();await login(page,'child');await expect(page.locator('[data-kanban-task="ui-private-'+browserName+'"]')).toHaveCount(0);await page.getByRole('button',{name:'Kanban',exact:true}).click();await page.getByRole('button',{name:'Chọn bảng Kanban',exact:true}).click();await page.getByRole('option',{name:'Synthetic Kanban child '+browserName,exact:true}).click();await expect(page.locator('[data-kanban-column]')).toHaveCount(7);await expect(page.locator('[data-kanban-task="ui-private-'+browserName+'"]')).toHaveCount(0);await expect(page.getByText('Synthetic UI private member '+browserName,{exact:true})).toHaveCount(0);await expect(page.getByText('Quy trình',{exact:true})).toHaveCount(7);await expect(page.locator('[data-kanban-column] input[type="checkbox"]')).toHaveCount(0);await expect(page.getByRole('button',{name:'Kanban hiện có',exact:true})).toBeVisible();const listed=await matrixRequest(page,'/views');expect(listed.status).toBe(200);const view=listed.body.views.find((v:any)=>v.title==='Synthetic Kanban child '+browserName);expect(view).toBeTruthy();const changed=await matrixRequest(page,'/views','POST',{expectedRevision:view.revision,input:{id:view.id,title:view.title,filter:view.filter,kind:'list',config:{kind:'list',sort:'rank',group:'none'}}});expect(changed.status).toBe(200);await expect(page.locator('[data-kanban-column]')).toHaveCount(0);await expect(page.getByRole('button',{name:'Chọn bảng Kanban',exact:true})).toContainText('Chọn bảng');await expect(page.getByRole('button',{name:'Tải lại',exact:true})).toHaveCount(0);
